command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-selection-identity --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "0714dd8f5d6420d967a84ce0c946b1c11a476d91") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-selection-identity origin/work/large-folder-selection-identity
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "6be98c5a48a075104a6e66dbb201f284f3f47172") { throw "candidate mismatch" }

python -X utf8 tests\winui\test_large_folder_streaming_contract.py
if ($LASTEXITCODE -ne 0) { throw "streaming source contract failed" }
python -X utf8 tests\winui\test_large_folder_contract.py
if ($LASTEXITCODE -ne 0) { throw "large-folder source contract failed" }

cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

$env:FLY_MIGRATION_CONFIGURATION = "Release"
$env:FLY_M21_OWNED_FEATURES = "YES"
python -X utf8 tests\winui\test_shell_gui.py
if ($LASTEXITCODE -ne 0) { throw "focused M21 selected-row GUI failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_SELECTION_IDENTITY_ACCEPTANCE_PASS"
